import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Glosario","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/glossary.md","filePath":"es/guide/glossary.md"}'),n={name:"es/guide/glossary.md"};function d(s,a,o,l,c,p){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="glossary" tabindex="-1">Glosario <a class="header-anchor" href="#glossary" aria-label="Enlace permanente a &quot;Glosario&quot;">​</a></h1><p><strong>Estado:</strong> Vocabulario del diseño · Cada mecánica conserva su estado indicado.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li><a href="/Syrolands-Public/es/guide/characters/skills.html">Skill</a>, <a href="/Syrolands-Public/es/guide/characters/techniques.html">Technique</a>, <a href="/Syrolands-Public/es/guide/characters/familiarity.html">Familiarity</a> y <a href="/Syrolands-Public/es/guide/glossary.html#mastery">Mastery</a> describen formas distintas de progresar.</li><li>Conocer una opción, prepararla y utilizarla con éxito son pasos separados.</li><li>Usa estas definiciones al leer; consulta las especificaciones enlazadas para ver las reglas detalladas.</li></ul><h2 id="terms-at-a-glance" tabindex="-1">Términos de un vistazo <a class="header-anchor" href="#terms-at-a-glance" aria-label="Enlace permanente a &quot;Términos de un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Término</th><th>Significado</th></tr></thead><tbody><tr><td><span id="skill"></span><a href="/Syrolands-Public/es/guide/characters/skills.html">Skill</a></td><td>Habilidad: capacidad del personaje en una actividad amplia; no es todo el catálogo de opciones aprendidas.</td></tr><tr><td><span id="technique"></span><a href="/Syrolands-Public/es/guide/characters/techniques.html">Technique</a></td><td>Técnica: opción o método aprendido; tener suficiente habilidad no enseña automáticamente todas las técnicas.</td></tr><tr><td><span id="familiarity"></span><a href="/Syrolands-Public/es/guide/characters/familiarity.html">Familiarity</a></td><td>Fluidez práctica con una acción o patrón concreto; distinta de aprenderlo y de la habilidad general.</td></tr><tr><td><span id="mastery"></span>Mastery</td><td>Dominio: experiencia profunda o especialización; no equivale a una cifra de habilidad ni al estado de Familiarity llamado Mastered.</td></tr><tr><td><span id="special-attack"></span><a href="/Syrolands-Public/es/guide/combat/special-attacks.html">Special Attack (SA)</a></td><td>Ataque especial: acción marcial aprendida con una utilidad, un compromiso y un coste propios.</td></tr><tr><td><span id="legacy-combat"></span><a href="/Syrolands-Public/es/guide/combat/legacy-and-modern.html">Legacy Combat</a></td><td>Combate de cadencia automática, conservado como alternativa compatible con el diseño.</td></tr><tr><td><span id="modern-combat"></span><a href="/Syrolands-Public/es/guide/combat/legacy-and-modern.html">Modern Combat</a></td><td>El jugador elige cuándo iniciar una acción disponible; elegir el momento no garantiza el éxito.</td></tr><tr><td><span id="flow"></span><a href="/Syrolands-Public/es/guide/combat/flow.html">Flow</a></td><td>Ritmo de combate sostenible condicionado por las acciones, el esfuerzo y la recuperación.</td></tr><tr><td><span id="core-pattern"></span><a href="/Syrolands-Public/es/guide/magic/learning-spells.html">Core Pattern</a></td><td>Estructura base del hechizo aprendida; las variantes pueden modificarla sin borrar su identidad.</td></tr><tr><td><span id="active-memory"></span><a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Active Memory</a></td><td>Memoria activa: selección de patrones aprendidos preparados para acceder de inmediato al lanzamiento normal, no para lanzar instantáneamente.</td></tr><tr><td><span id="concentration"></span><a href="/Syrolands-Public/es/guide/magic/meditation-and-concentration.html">Concentration</a></td><td>Concentración: estabilidad bajo presión al lanzar o sostener un trabajo mental adecuado; no añade automáticamente otro coste al límite de habilidades.</td></tr><tr><td><span id="local-trauma"></span><a href="/Syrolands-Public/es/guide/combat/limbs-and-trauma.html">Local Trauma</a></td><td>Trauma local: daño estructural en una región corporal, distinto del daño a la salud global.</td></tr><tr><td><span id="global-hits"></span><a href="/Syrolands-Public/es/guide/combat/limbs-and-trauma.html">Global Hits</a></td><td>Salud global, que coexiste con el estado local de las regiones corporales.</td></tr><tr><td><span id="masterwork"></span><a href="/Syrolands-Public/es/guide/items/item-quality.html">Masterwork</a></td><td>Obra maestra: logro artesanal excepcional dentro de la propuesta de calidad; no es automáticamente un objeto mágico.</td></tr><tr><td><span id="latent-property"></span><a href="/Syrolands-Public/es/guide/items/item-quality.html">Latent Property</a></td><td>Propiedad latente: posible potencial oculto revelado mediante uso o descubrimiento adecuados; no está garantizado en todo buen objeto.</td></tr><tr><td><span id="profession-path"></span><a href="/Syrolands-Public/es/guide/professions/overview.html">Profession Path</a></td><td>Especialización dentro de una profesión, expresada mediante conocimientos y técnicas, sin exigir una habilidad independiente.</td></tr><tr><td><span id="prepared-repertoire"></span><a href="/Syrolands-Public/es/guide/combat/special-attacks.html">Prepared Repertoire</a></td><td>Repertorio preparado: opciones marciales elegidas para tenerlas a mano; separado de Active Memory mágica y sin exigir invertir en INT.</td></tr><tr><td><span id="wind-up"></span>Wind-up</td><td>Preparación anterior al contacto de una acción; iniciarla no produce un impacto instantáneo.</td></tr><tr><td><span id="active-window"></span>Active Window</td><td>Ventana activa: fase en la que una acción puede conectar, sujeta a sus comprobaciones; no promete impactos repetidos.</td></tr><tr><td><span id="recovery"></span><a href="/Syrolands-Public/es/guide/combat/stamina-and-reactive-combat.html">Recovery</a></td><td>Recuperación de la acción: compromiso restante antes de iniciar otra acción válida; no equivale a curar una lesión.</td></tr><tr><td><span id="reach"></span><a href="/Syrolands-Public/es/guide/combat/reach-and-spacing.html">Reach</a></td><td>Alcance físico máximo de una acción concreta; la habilidad no lo alarga de forma invisible.</td></tr><tr><td><span id="effective-range"></span><a href="/Syrolands-Public/es/guide/combat/reach-and-spacing.html">Effective Range</a></td><td>Distancia eficaz o preferida para una acción; estar dentro del alcance máximo no asegura un manejo ideal.</td></tr><tr><td><span id="telegraph"></span>Telegraph</td><td>Señal anticipada, como postura, movimiento o sonido, que puede ayudar a interpretar una acción; no garantiza el resultado ni dicta una respuesta.</td></tr><tr><td><span id="consistency"></span>Consistency</td><td>Consistencia: regularidad de la ejecución o los resultados; distinta de la probabilidad de acertar y sin garantizar el éxito.</td></tr><tr><td><span id="handling"></span>Handling</td><td>Manejo: control, coste de stamina y recuperación de un objeto o acción dentro de su función; no es simplemente daño adicional.</td></tr><tr><td><span id="stamina"></span><a href="/Syrolands-Public/es/guide/combat/stamina-and-reactive-combat.html">Stamina</a></td><td>Recurso físico por el que compiten las acciones marciales propuestas; los costes y las reglas del máximo siguen sin cerrarse.</td></tr><tr><td><span id="fatigue"></span>Fatigue</td><td>Fatiga: presión del esfuerzo sobre la actividad sostenida; sigue sin resolverse si deriva de stamina o se representa por separado.</td></tr><tr><td><span id="counter"></span>Counter</td><td>Respuesta adecuada a una acción o situación rival; importan el momento, los requisitos y la compatibilidad, sin garantizar un impacto.</td></tr><tr><td><span id="brace"></span><a href="/Syrolands-Public/es/guide/combat/special-attacks.html">Brace</a></td><td>Respuesta defensiva propuesta con compromiso frente a ataques compatibles; fintas, retrasos o flancos pueden superarla, y un intento desperdiciado sigue costando tiempo y stamina.</td></tr><tr><td><span id="riposte"></span><a href="/Syrolands-Public/es/guide/combat/special-attacks.html">Riposte</a></td><td>Respuesta defensiva candidata con requisitos de tiempo, recursos y compatibilidad; su comportamiento exacto no está cerrado.</td></tr></tbody></table><h2 id="what-s-new-in-syrolands" tabindex="-1">Qué aporta Syrolands <a class="header-anchor" href="#what-s-new-in-syrolands" aria-label="Enlace permanente a &quot;Qué aporta Syrolands&quot;">​</a></h2><p>Estos términos conectan la capacidad del personaje, las decisiones del jugador y el conocimiento aprendido entre sistemas. Algunos nombres son conocidos por UO, pero esta guía utiliza las definiciones de Syrolands; Mastery no equivale automáticamente al sistema posterior Skill Masteries de UO.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Aprendes una Technique, mejoras su Familiarity mediante la práctica y la eliges para tu Prepared Repertoire. Tu Skill sigue importando al intentar usarla; tenerla preparada no garantiza un impacto.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/introduction.html">Introducción</a> · <a href="/Syrolands-Public/es/guide/characters/techniques.html">Técnicas</a> · <a href="/Syrolands-Public/es/guide/characters/familiarity.html">Familiarity</a> · <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Memoria de hechizos</a></p><h2 id="full-design-specification" tabindex="-1">Especificación completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/">Especificaciones de diseño: todos los sistemas y definiciones detalladas</a></p>',14)])])}const h=e(n,[["render",d]]);export{m as __pageData,h as default};
